#include <fstream>
#include <unordered_map>
#include <vector>
#include <cstdint>

void write_huffman_dictionary(std::ofstream &outfile, const std::unordered_map<unsigned char, std::string> &huffman_codes) {
    // Write the size of the dictionary
    uint32_t size = static_cast<uint32_t>(huffman_codes.size());
    outfile.write(reinterpret_cast<const char*>(&size), sizeof(size));

    // Write each character, code length, and code
    for (const auto &pair : huffman_codes) {
        unsigned char character = pair.first;
        const std::string &code = pair.second;
        uint8_t code_length = static_cast<uint8_t>(code.size());

        // Write the character
        outfile.write(reinterpret_cast<const char*>(&character), sizeof(character));

        // Write the code length
        outfile.write(reinterpret_cast<const char*>(&code_length), sizeof(code_length));

        // Write the code as bytes
        // Each byte represents 8 bits of the code
        // Pad the last byte with zeros if necessary
        uint8_t byte = 0;
        int bit_pos = 0;
        for (char bit : code) {
            if (bit == '1') {
                byte |= (1 << (7 - bit_pos));
            }
            bit_pos++;
            if (bit_pos == 8) {
                outfile.write(reinterpret_cast<const char*>(&byte), sizeof(byte));
                byte = 0;
                bit_pos = 0;
            }
        }
        // Write the last byte if it contains any bits
        if (bit_pos > 0) {
            outfile.write(reinterpret_cast<const char*>(&byte), sizeof(byte));
        }
    }
}

